/**
 * Parses a named-registry specifier of the form '<alias>:<body>' (e.g. 'gh:@acme/foo@^1.0.0').
 *
 * Returns null when:
 * - the specifier does not use a recognised alias (e.g. 'npm:', 'jsr:', 'catalog:', 'workspace:' or the 'github:' git shorthand);
 * - the alias is not present in knownRegistryNames;
 * - the body is a bare version selector (e.g. '^1.0.0') but no packageAlias is provided to derive the package name from.
 *
 * Throws when the body names a scope but no valid package name (e.g. '@acme', '@acme/', '@acme@1.0.0').
 */
export function parseNamedRegistrySpecifierToRegistryPackageSpec (
